L(OA15, 4,
  mat=MAT_DATOS,
  use="Aprenderé a decir cuántas personas hay sobre o bajo un percentil o un cuartil en una población, y a interpretar frases como «está en el percentil 85».",
  prior=["Sé qué es un percentil.", "Sé calcular el porcentaje de una cantidad."],
  explain=[
      "Una población es el grupo completo que se estudia. Si un valor está en el percentil p, entonces el p % de la población tiene un valor menor o igual, y el (100 − p) % tiene uno mayor. Por ejemplo, con 150 personas y percentil 80, hay 120 personas bajo o igual y 30 sobre.",
      "Los cuartiles son percentiles: Q1 es el percentil 25, Q2 el 50 y Q3 el 75. Sobre Q3 queda el 25 % de la población y bajo Q1 queda el 25 %. Para calcular cuántas personas son, se multiplica el total por el porcentaje y se divide por 100.",
      "Cuidado con dos errores. El primero es creer que el percentil 90 es un puntaje de 90 puntos: es una posición en el grupo, no un puntaje. El segundo es comparar grupos de distinto tamaño: el percentil 70 de un curso de 30 y el percentil 70 de un curso de 60 dejan bajo el valor a 21 y a 42 personas, respectivamente.",
  ],
  vocab=[("población", "grupo completo que se estudia"), ("sobre el percentil", "con un valor mayor que el del percentil"), ("bajo el percentil", "con un valor menor o igual que el del percentil"), ("posición", "lugar que ocupa un valor dentro de un grupo ordenado")],
  worked=[
      ("Percentil 80 de 150 personas", "Un puntaje está en el percentil 80 de una población de 150 personas. ¿Cuántas personas están bajo o igual y cuántas sobre?", ["Bajo o igual: 80 % de 150 = 150 × 80 ÷ 100 = 120.", "Sobre: 150 − 120 = 30."], "120 bajo o igual y 30 sobre"),
      ("Percentil 35 de 200 niños", "La estatura de Sofía está en el percentil 35 en un grupo de 200 niños. ¿Cuántos niños tienen su estatura o menos?", ["35 % de 200 = 200 × 35 ÷ 100.", "200 × 35 = 7.000 y 7.000 ÷ 100 = 70."], "70 niños tienen su estatura o menos"),
  ],
  mist=[
      ("Decir que estar en el percentil 90 es sacar 90 puntos.", "El percentil es una posición en el grupo, no un puntaje.", "Di: «el 90 % del grupo tiene un valor igual o menor»."),
      ("Comparar la cantidad de personas entre dos grupos de distinto tamaño usando solo el percentil.", "El mismo percentil deja una cantidad distinta de personas si el total cambia.", "Multiplica el porcentaje por el total de cada grupo."),
  ],
  R=[arith("En una población de 200 personas, ¿cuántas están bajo o igual al percentil 50?", "200*50//100", "El 50 % de 200 es la cantidad por debajo o igual.", " personas"),
     ex("¿Qué porcentaje de la población queda sobre el percentil 90?", "10 %", "100 % − 90 % = 10 %."),
     ex("¿Con qué percentil coincide el tercer cuartil Q3?", "Con el percentil 75", "Q3 deja el 75 % de los datos bajo o igual.")],
  C=[arith("En una población de 300 personas, ¿cuántas están bajo o igual al percentil 60?", "300*60//100", "El 60 % de 300 es la cantidad por debajo o igual.", " personas"),
     arith("En una población de 120 personas, ¿cuántas están sobre el percentil 75?", "120-120*75//100", "Se restan las 90 personas bajo o igual al total.", " personas"),
     arith("En un grupo de 60 datos, ¿cuántos hay sobre el primer cuartil Q1?", "60-60*25//100", "Q1 es el percentil 25 y se restan los 15 que están bajo o igual.", " datos")],
  A=[arith("De 500 estudiantes, ¿cuántos están sobre el percentil 85?", "500-500*85//100", "Sobre el percentil 85 queda el 15 % de la población.", " estudiantes"),
     arith("En un grupo de 80 datos, 20 son menores o iguales que cierto valor. ¿En qué percentil está ese valor?", "20*100//80", "El percentil es el porcentaje de datos por debajo o igual.", ""),
     arith("En una ciudad de ejemplo con 40.000 personas, un ingreso está en el percentil 30. ¿Cuántas personas tienen un ingreso mayor?", "40000-40000*30//100", "El 70 % de las personas tiene un ingreso mayor.", " personas")],
  Z=[ex("Un estudiante dice que quien está en el percentil 90 de una prueba tuvo un 90 % de logro. ¿Es cierto? Responde sí o no.", "No", "El percentil 90 indica que el 90 % del grupo tuvo un puntaje igual o menor."),
     ex("Un puntaje está en el percentil 70 de un curso de 30 estudiantes y también en el percentil 70 de otro curso de 60. ¿Dejan bajo el puntaje la misma cantidad de estudiantes? Responde sí o no.", "No", "En el curso de 30 son 21 estudiantes y en el de 60 son 42.")],
  D=[arith("En cierto grupo, 12 personas están bajo o igual al percentil 25. ¿Cuántas personas tiene el grupo?", "12*100//25", "Las 12 personas son el 25 % del total.", " personas"),
     arith("Entre el percentil 25 y el percentil 75 hay 36 datos. ¿Cuántos datos tiene el conjunto completo?", "36*2", "Entre esos percentiles está el 50 % de los datos, así que el total es el doble.", " datos")],
  ctx=[arith("Un puntaje de ejemplo está en el percentil 80 entre 2.000 postulantes. ¿Cuántos postulantes tienen un puntaje mayor?", "2000-2000*80//100", "El 20 % de 2.000 tiene un puntaje mayor.", " postulantes")],
  chk=[ex("Si estás en el percentil 40, ¿qué porcentaje del grupo tiene un valor mayor que el tuyo?", "60 %", "100 % − 40 % = 60 %."),
       arith("De 50 datos, ¿cuántos hay bajo o igual al percentil 10?", "50*10//100", "El 10 % de 50 es la cantidad por debajo o igual.", " datos"),
       ex("¿El percentil es un puntaje o una posición dentro del grupo?", "Una posición dentro del grupo", "Indica qué porcentaje del grupo queda por debajo o igual.")],
  open=("Imagina un grupo de ejemplo de 400 personas. Un valor está en el percentil 70. Escribe cuántas personas tienen un valor menor o igual y cuántas mayor. Luego escribe en dos frases cómo explicarías a un amigo qué significa «estar en el percentil 70» sin decir que es un puntaje.",
        "280 personas tienen un valor menor o igual y 120 tienen uno mayor. Estar en el percentil 70 significa que el 70 % del grupo tiene un valor igual o menor que el mío; no es un puntaje, es mi posición en el grupo.",
        ["calcula las dos cantidades", "explica el significado en dos frases", "evita decir que es un puntaje"],
        ["dos cálculos", "explicación escrita"],
        ["decir que el percentil es un puntaje", "sumar mal las cantidades", "no usar el total de 400"],
        "Pide que explique con sus palabras qué significa el 70 %. Reconoce que distinga posición de puntaje."),
  reinforce="En un grupo de 250 personas, calcula cuántas están bajo o igual al percentil 40 y cuántas sobre él.",
  extend="Explica por qué el valor máximo del grupo deja a todo el grupo, el 100 %, con valores menores o iguales que él.")

L(OA15, 5,
  mat=MAT_DATOS,
  use="Aprenderé a comparar dos distribuciones usando sus diagramas de caja, y a hacerlo con cautela: sin sacar conclusiones demasiado fuertes de pocos datos.",
  prior=["Sé leer un diagrama de caja.", "Sé calcular el RIC."],
  explain=[
      "Para comparar dos diagramas de caja se miran tres cosas. Primero, el centro: qué mediana es mayor. Segundo, la dispersión: qué caja es más larga, o sea, qué RIC es mayor. Tercero, la extensión total y si hay traslape: cuánto se cruzan los valores de los dos grupos.",
      "Comparar con cautela quiere decir no exagerar. Una mediana mayor no significa que todos los datos de ese grupo sean mayores, porque los diagramas se pueden traslapar. Hay que revisar cuántos datos tiene cada grupo: con pocos datos, el diagrama puede cambiar mucho. Y hay que cuidarse de decir que algo «causa» la diferencia, porque el diagrama solo describe.",
      "Una forma de decirlo bien es: «En el grupo B la mediana es mayor, pero los dos grupos se traslapan, por lo que no se puede asegurar que cada integrante de B supere a los de A». También sirve usar los cuartiles: si Q1 de B es mayor que la mediana de A, entonces al menos el 75 % de B supera a la mitad de A.",
  ],
  vocab=[("traslape", "zona de valores que comparten dos grupos"), ("cautela", "cuidado de no concluir más de lo que muestran los datos"), ("centro", "valor típico de un grupo, como la mediana"), ("distribución", "forma en que se reparten los valores de un grupo")],
  worked=[
      ("Mismo centro, distinta dispersión", "El grupo A tiene mínimo 20, Q1 30, mediana 40, Q3 50 y máximo 60. El grupo B tiene mínimo 25, Q1 35, mediana 40, Q3 45 y máximo 55. Compáralos.", ["Las medianas son iguales: 40 en ambos.", "RIC de A: 50 − 30 = 20. RIC de B: 45 − 35 = 10.", "B es más concentrado alrededor de la mediana."], "Mismo centro; A está más disperso que B"),
      ("Qué se puede asegurar", "El grupo A tiene mediana 60 y el grupo B tiene Q1 igual a 62. ¿Qué parte de B supera a la mediana de A?", ["Q1 de B es 62, que es mayor que 60.", "Sobre Q1 está el 75 % de B."], "Al menos el 75 % de B supera la mediana de A"),
  ],
  mist=[
      ("Concluir que todos los del grupo con mayor mediana superan a todos los del otro.", "Los diagramas pueden traslaparse.", "Compara también mínimos, máximos y cuartiles."),
      ("Decir que un grupo es mejor sin mirar cuántos datos tiene cada uno.", "Con pocos datos, el resultado es poco confiable.", "Anota el tamaño de cada grupo antes de concluir."),
  ],
  R=[ex("¿Qué medida de un diagrama de caja indica el centro de los datos?", "La mediana", "Es el valor central."),
     arith("Un grupo tiene Q1 = 30 y Q3 = 50. ¿Cuánto vale su RIC?", "50-30", "RIC = Q3 − Q1."),
     ex("Dos grupos tienen la misma mediana, pero la caja del grupo X es más larga que la del grupo Y. ¿Cuál tiene los datos más dispersos?", "X", "Una caja más larga significa un RIC mayor.")],
  C=[ex("El grupo X tiene Q1 = 12, mediana 18 y Q3 = 30. El grupo Y tiene Q1 = 10, mediana 22 y Q3 = 26. ¿Cuál tiene la mediana mayor?", "Y", "22 es mayor que 18."),
     ex("El grupo X tiene Q1 = 12 y Q3 = 30. El grupo Y tiene Q1 = 10 y Q3 = 26. ¿Cuál tiene el menor RIC?", "Y", "El RIC de Y es 16 y el de X es 18."),
     ex("Dos grupos tienen cajas que se cruzan entre 40 y 50. ¿Todos los datos de un grupo son mayores que los del otro? Responde sí o no.", "No", "Hay valores compartidos en la zona de traslape.")],
  A=[ex("El grupo A tiene mínimo 30, Q1 42, mediana 50, Q3 58 y máximo 66. El grupo B tiene mínimo 25, Q1 46, mediana 54, Q3 62 y máximo 70. ¿Cuál tiene la mediana más alta?", "B", "54 es mayor que 50."),
     ex("Con los mismos datos de A y de B, ¿los dos grupos tienen igual RIC? Responde sí o no.", "Sí", "El RIC de A es 58 − 42 = 16 y el de B es 62 − 46 = 16."),
     ex("Con esos mismos datos, ¿se puede asegurar que cada integrante de B supera a todos los de A? Responde sí o no.", "No", "El mínimo de B es 25, menor que el máximo de A, que es 66.")],
  Z=[ex("Valentina compara dos colegios con diagramas de caja y concluye que el colegio X es mejor porque su mediana es mayor, pero X tiene 12 estudiantes y Y tiene 400. ¿Es una conclusión segura? Responde sí o no.", "No", "Con solo 12 datos el diagrama de X puede cambiar mucho."),
     ex("Dos grupos tienen la misma mediana y el mismo RIC. ¿Tienen necesariamente los mismos datos? Responde sí o no.", "No", "Pueden diferir en el mínimo, el máximo y en los datos que no entran en esas medidas.")],
  D=[arith("El grupo A tiene Q1 = 40 y Q3 = 60. El grupo B tiene Q1 = 45 y Q3 = 55. ¿Cuántas veces es mayor el RIC de A que el de B?", "(60-40)//(55-45)", "Los RIC son 20 y 10.", " veces"),
     ex("La mediana de B es 54 y la mediana de A es 50. ¿Al menos la mitad de B supera la mediana de A? Responde sí o no.", "Sí", "La mitad de B tiene valores iguales o mayores que 54, que es mayor que 50.")],
  ctx=[ex("Los tiempos de reparto de ejemplo, en minutos, de dos repartidores son: Ana con Q1 = 20, mediana 25 y Q3 = 30; Luis con Q1 = 22, mediana 25 y Q3 = 40. Con la misma mediana, ¿quién es más regular, es decir, menos disperso?", "Ana", "Su RIC es 10 y el de Luis es 18.")],
  chk=[ex("¿Qué tres cosas se miran al comparar dos diagramas de caja?", "El centro, la dispersión y el traslape", "Así se compara sin exagerar."),
       ex("¿Qué se debe revisar para no concluir de más: el tamaño de los grupos o el color del gráfico?", "El tamaño de los grupos", "Con pocos datos las conclusiones son poco confiables."),
       ex("¿Un diagrama de caja demuestra que una variable causa la diferencia entre dos grupos? Responde sí o no.", "No", "El diagrama solo describe los datos.")],
  open=("Compara con cautela estos dos grupos de ejemplo. Grupo 8.º A (30 estudiantes): mínimo 30, Q1 42, mediana 50, Q3 58, máximo 66. Grupo 8.º B (30 estudiantes): mínimo 25, Q1 46, mediana 54, Q3 62, máximo 70. Escribe tres frases: una sobre el centro, una sobre la dispersión y una sobre el traslape. Termina con una frase que diga qué no se puede asegurar.",
        "La mediana de B (54) es mayor que la de A (50). Los dos RIC son 16. Las cajas se traslapan entre 46 y 58. No se puede asegurar que cada estudiante de B supere a los de A.",
        ["compara las medianas", "compara los RIC", "describe el traslape", "escribe lo que no se puede asegurar"],
        ["tres frases de comparación", "frase de cautela"],
        ["concluir que todos los de B superan a los de A", "confundir RIC con rango", "no mencionar el tamaño de los grupos"],
        "Pide que justifique cada frase con un número. Reconoce que incluya una advertencia."),
  reinforce="Compara dos grupos con RIC de 8 y 14 y la misma mediana, y escribe cuál está más disperso.",
  extend="Explica qué datos adicionales pedirías para decidir si la diferencia entre dos grupos es importante.")
